export const BOX = { length: 0.464, width: 0.290, height: 0.214 };
export const SCALE = 0.0547;

// Centerlines traced from Layout03. Coordinates are on a 1900 px-wide drawing.
export function path(points) {
  const lengths = [0];
  for (let i = 1; i < points.length; i++) {
    lengths.push(lengths[i - 1] + Math.hypot(points[i][0] - points[i - 1][0], points[i][1] - points[i - 1][1]) * SCALE);
  }
  return { points, lengths, length: lengths.at(-1) };
}

export function pointAt(route, distance) {
  const d = Math.max(0, Math.min(route.length, distance));
  let low = 1;
  let high = route.points.length - 1;
  while (low < high) {
    const middle = (low + high) >> 1;
    if (route.lengths[middle] < d) low = middle + 1;
    else high = middle;
  }
  const [x, y] = route.points[low - 1];
  const [x2, y2] = route.points[low];
  const fraction = (d - route.lengths[low - 1]) / (route.lengths[low] - route.lengths[low - 1]);
  return [x + (x2 - x) * fraction, y + (y2 - y) * fraction, Math.atan2(y2 - y, x2 - x)];
}

export function distanceAt(route, [x, y]) {
  let closest = Infinity;
  let distance = 0;
  for (let i = 1; i < route.points.length; i++) {
    const [ax, ay] = route.points[i - 1];
    const [bx, by] = route.points[i];
    const dx = bx - ax;
    const dy = by - ay;
    const fraction = Math.max(0, Math.min(1, ((x - ax) * dx + (y - ay) * dy) / (dx * dx + dy * dy)));
    const offset = Math.hypot(ax + fraction * dx - x, ay + fraction * dy - y);
    if (offset < closest) {
      closest = offset;
      distance = route.lengths[i - 1] + fraction * (route.lengths[i] - route.lengths[i - 1]);
    }
  }
  return distance;
}

