export const stations = [upper, lower].flatMap((records, group) => records.map(([name, rate, points, alternative]) => {
  const route = path(points);
  return { name, rate, group, route, alternative, junction: distanceAt(groups[group].route, points[0]), capacity: Math.max(1, Math.floor(route.length / BOX.length)) };
}));
